mapper.select:
SELECT id, room_id, seat_no, zone, has_power, status
FROM lib_seat
WHERE id = #{id}

SELECT s.id, s.room_id, s.seat_no, s.zone, s.has_power, s.status
FROM lib_seat s
WHERE s.room_id = #{roomId}
AND s.status = 1
AND NOT EXISTS (
SELECT 1
FROM seat_booking b
WHERE b.seat_id = s.id
AND b.book_date = #{bookDate}
AND b.status IN ('BOOKED', 'CHECKED_IN', 'LEAVING')
AND b.start_time < #{endTime}
AND b.end_time > #{startTime}
)
ORDER BY s.seat_no

mapper.update:
UPDATE lib_seat
SET zone = #{zone}, has_power = #{hasPower}, status = #{status}
WHERE id = #{id}

mapper.select:
SELECT COUNT(*) FROM seat_booking
WHERE seat_id = #{seatId}
AND status IN ('BOOKED', 'CHECKED_IN', 'LEAVING')
